import React, { useState, useEffect } from 'react';
import { Bar } from 'react-chartjs-2';
import api from '../../services/api';
import { useAuth } from '../../context/AuthContext';

const Dashboard = () => {
    const { user } = useAuth();
    const [stats, setStats] = useState({
        totalEmployees: 0,
        presentToday: 0,
        absentToday: 0,
        lateToday: 0
    });

    useEffect(() => {
        fetchStats();
    }, []);

    const fetchStats = async () => {
        try {
            const today = new Date().toISOString().split('T')[0];
            const [employeesRes, attendanceRes] = await Promise.all([
                api.get('/employees'),
                api.get(`/attendance/report?startDate=${today}&endDate=${today}`)
            ]);

            const attendance = attendanceRes.data.data;
            setStats({
                totalEmployees: employeesRes.data.data.length,
                presentToday: attendance.filter(a => a.Status === 'Present').length,
                absentToday: attendance.filter(a => !a.CheckInTime).length,
                lateToday: attendance.filter(a => a.Status === 'Late').length
            });
        } catch (error) {
            console.error('Error fetching stats:', error);
        }
    };

    const chartData = {
        labels: ['Present', 'Absent', 'Late'],
        datasets: [
            {
                label: 'Today\'s Attendance',
                data: [stats.presentToday, stats.absentToday, stats.lateToday],
                backgroundColor: [
                    'rgba(75, 192, 192, 0.6)',
                    'rgba(255, 99, 132, 0.6)',
                    'rgba(255, 206, 86, 0.6)'
                ],
                borderColor: [
                    'rgba(75, 192, 192, 1)',
                    'rgba(255, 99, 132, 1)',
                    'rgba(255, 206, 86, 1)'
                ],
                borderWidth: 1
            }
        ]
    };

    return (
        <div className="container mt-4">
            <h2>Dashboard</h2>
            <div className="row mt-4">
                <div className="col-md-3">
                    <div className="card text-white bg-primary mb-3">
                        <div className="card-body">
                            <h5 className="card-title">Total Employees</h5>
                            <h2>{stats.totalEmployees}</h2>
                        </div>
                    </div>
                </div>
                <div className="col-md-3">
                    <div className="card text-white bg-success mb-3">
                        <div className="card-body">
                            <h5 className="card-title">Present Today</h5>
                            <h2>{stats.presentToday}</h2>
                        </div>
                    </div>
                </div>
                <div className="col-md-3">
                    <div className="card text-white bg-danger mb-3">
                        <div className="card-body">
                            <h5 className="card-title">Absent Today</h5>
                            <h2>{stats.absentToday}</h2>
                        </div>
                    </div>
                </div>
                <div className="col-md-3">
                    <div className="card text-white bg-warning mb-3">
                        <div className="card-body">
                            <h5 className="card-title">Late Today</h5>
                            <h2>{stats.lateToday}</h2>
                        </div>
                    </div>
                </div>
            </div>
            <div className="row">
                <div className="col-md-8">
                    <div className="card">
                        <div className="card-header">
                            <h5>Attendance Overview</h5>
                        </div>
                        <div className="card-body">
                            <Bar data={chartData} options={{ responsive: true }} />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
